def durchschnitt(punkte, anzahl):
    try:
        return punkte / anzahl
    except ZeroDivisionError:
        print("Anzahl darf nicht 0 sein")
    except TypeError as fehler:
        print(f"Falscher Typ: {fehler}")

durchschnitt(10, 0)
durchschnitt(10, "2")

for text in ["4", "x"]:
    try:
        zahl = int(text)
    except ValueError:
        print(f"{text}: keine Zahl")
    else:
        print(f"{text}: Quadrat ist {zahl * zahl}")
    finally:
        print("geprüft")

while True:
    try:
        note = int(input("Note (1-5): "))
        break
    except ValueError:
        print("Das war keine Zahl.")
print(f"Gespeichert: {note}")

